@startuml

class Well {
  + code : string
}

abstract class WellCategory {}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + yearOfInstallation : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

OnshoreWell --|> Well
OffshoreWell --|> Well
Well --|> WellCategory

Well "1" -- "*" Extraction
OilCompany "1" -- "*" Extraction
Extraction "*" -- "1" Well
Extraction "*" -- "1" OilCompany

OffshoreWell "1" o-- "0..1" GeographicalArea

@enduml

